  for(const key of ['gangTypes','fighterTypes','equipment','weaponProfiles','skills','coreRules','territories','weaponTraits','equipmentAvailability']){assert(catalog[key].length>0,key+' restored');for(const row of catalog[key])assert.equal(row.source_verified,true,key+' '+row.id);}
  assert(catalog.fighterTypes.some(x=>x.id.startsWith('official-001-')));assert(catalog.fighterTypes.some(x=>x.id.includes('002')));assert(catalog.coreRules.some(x=>x.id==='n26-core-xp-events'));
